package com.foodflow.delivery.client;import org.springframework.cloud.openfeign.FeignClient;import org.springframework.web.bind.annotation.*;import java.util.List;import java.util.Map;import java.util.UUID;
@FeignClient(name="order-service",url="${foodflow.order.url:}",configuration=com.foodflow.delivery.config.FeignConfig.class) public interface OrderClient {@GetMapping("/api/orders/internal/delivery-ready") List<UUID> readyForDelivery();@GetMapping("/api/orders/internal/{id}/delivery-check") Map<String,Object> check(@PathVariable UUID id);@PostMapping("/api/orders/internal/{id}/delivery-status") void update(@PathVariable UUID id,@RequestParam String status,@RequestParam boolean cashCollected);}
